                    { "type": "external", "trigger": "toggleAudio", "target": "Mono" }
                  ]
                },
                {
                  "name": "Mono",
                  "type": "state",
                  "transitions": [
                    { "type": "external", "trigger": "toggleAudio", "target": "Stereo" }
                  ]
                }
              ]
            },
            {
              "name": "video",
              "initial": { "target": "HD" },
              "elements": [
                {
                  "name": "HD",
                  "type": "state",
                  "transitions": [
                    { "type": "external", "trigger": "lowBandwidth", "target": "SD" }
